original_code:
class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        p = sum(nums)
        found = False
        nums.sort(reverse=True)

        for v in nums:
            if v < p - v:
                found = True
                p -= v
                continue
            p -= v

        return p if found else -1

